function providerEntries(packet){
  if(!Array.isArray(packet.providers))throw new Error("Provider catalogue is missing its provider list.");
  var rows=packet.providers.filter(function(p){return p&&typeof p==="object"&&providerId(p.slug);}).slice();
  NATIVE_PROVIDERS.forEach(function(p){if(!rows.some(function(r){return r.slug===p.slug;}))rows.push(Object.assign({},p));});
